from collections import deque

def find_lexicographically_smallest_word(R, C, grid):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    min_word = 'z' * 21

    def bfs(start_row, start_col):
        nonlocal min_word
        queue = deque([(start_row, start_col)])
        visited = set()
        current_word = []

        while queue:
            row, col = queue.popleft()
            if (row, col) in visited or grid[row][col] == '#':
                continue
            visited.add((row, col))
            current_word.append(grid[row][col])

            for dr, dc in directions:
                new_row, new_col = row + dr, col + dc
                if 0 <= new_row < R and 0 <= new_col < C and (new_row, new_col) not in visited:
                    queue.append((new_row, new_col))

            if len(current_word) >= 2:
                current_word_str = ''.join(current_word)
                if current_word_str < min_word:
                    min_word = current_word_str

            if row > 0 and grid[row-1][col] != '#' and (row-1, col) not in visited:
                queue.append((row-1, col))

    for i in range(R):
        for j in range(C):
            bfs(i, j)

    return min_word

